import{_ as t,a0 as l,w as r,s as h,ao as o,I as p,x as a,a1 as e,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const v=JSON.parse('{"title":"查看一個歸檔或壓縮文件的內容而無需解壓它 | LCTT x X-CMD","titleTemplate":false,"description":"查看一個歸檔或壓縮文件的內容而無需解壓它 | LCTT (201809) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"查看一個歸檔或壓縮文件的內容而無需解壓它 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"查看一個歸檔或壓縮文件的內容而無需解壓它 | LCTT (201809) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201809/20180702 View The Contents Of An Archive Or Compressed File Without Extracting It","title":"查看一個歸檔或壓縮文件的內容而無需解壓它","tag":"201809","desc":""},"relativePath":"201809/20180702 View The Contents Of An Archive Or Compressed File Without Extracting It.md","filePath":"[post].md"}'),c={name:"201809/20180702 View The Contents Of An Archive Or Compressed File Without Extracting It.md"};function d(g,s,k,u,b,f){const n=l("Link");return r(),h("div",null,[s[15]||(s[15]=o(`<h1 id="查看一個歸檔或壓縮文件的內容而無需解壓它" tabindex="-1">查看一個歸檔或壓縮文件的內容而無需解壓它 <a class="header-anchor" href="#查看一個歸檔或壓縮文件的內容而無需解壓它" aria-label="Permalink to “查看一個歸檔或壓縮文件的內容而無需解壓它”">​</a></h1><p><img src="https://www.ostechnix.com/wp-content/uploads/2018/07/View-The-Contents-Of-An-Archive-Or-Compressed-File-720x340.png" alt=""></p><p>在本教程中，我們將學習如何在類 Unix 系統中查看一個歸檔或者壓縮文件的內容而無需實際解壓它。在深入之前，讓我們先釐清歸檔和壓縮文件的概念，它們之間有顯著不同。歸檔是將多個文件或者目錄歸併到一個文件的過程，因此這個生成的文件是沒有被壓縮過的。而壓縮則是結合多個文件或者目錄到一個文件並最終壓縮這個文件的方法。歸檔文件不是一個壓縮文件，但壓縮文件可以是一個歸檔文件，清楚了嗎？好，那就讓我們進入今天的主題。</p><h3 id="查看一個歸檔或者壓縮文件的內容而無需解壓它" tabindex="-1">查看一個歸檔或者壓縮文件的內容而無需解壓它 <a class="header-anchor" href="#查看一個歸檔或者壓縮文件的內容而無需解壓它" aria-label="Permalink to “查看一個歸檔或者壓縮文件的內容而無需解壓它”">​</a></h3><p>得益於 Linux 社區，有很多命令列工具可以來達成上面的目標。下面就讓我們來看看使用它們的一些示例。</p><h4 id="_1、使用-vim-編輯器" tabindex="-1">1、使用 vim 編輯器 <a class="header-anchor" href="#_1、使用-vim-編輯器" aria-label="Permalink to “1、使用 vim 編輯器”">​</a></h4><p>vim 不只是一個編輯器，使用它我們可以幹很多事情。下面的命令展示的是在沒有解壓的情況下使用 vim 查看一個壓縮的歸檔文件的內容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ vim ostechnix.tar.gz</span></span></code></pre></div><p><img src="http://www.ostechnix.com/wp-content/uploads/2018/07/vim.png" alt=""></p><p>你甚至還可以瀏覽歸檔文件的內容，打開其中的文本文件（假如有的話）。要打開一個文本文件，只需要用方向鍵將鼠標的游標放置到文件的前面，然後敲 ENTER 鍵來打開它。</p><h4 id="_2、使用-tar-命令" tabindex="-1">2、使用 tar 命令 <a class="header-anchor" href="#_2、使用-tar-命令" aria-label="Permalink to “2、使用 tar 命令”">​</a></h4><p>為了列出一個 tar 歸檔文件的內容，可以運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ tar -tf ostechnix.tar</span></span>
<span class="line"><span>ostechnix/</span></span>
<span class="line"><span>ostechnix/image.jpg</span></span>
<span class="line"><span>ostechnix/file.pdf</span></span>
<span class="line"><span>ostechnix/song.mp3</span></span></code></pre></div><p>或者使用 <code>-v</code> 選項來查看歸檔文件的具體屬性，例如它的文件所有者、屬組、創建日期等等。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ tar -tvf ostechnix.tar</span></span>
<span class="line"><span>drwxr-xr-x sk/users 0 2018-07-02 19:30 ostechnix/</span></span>
<span class="line"><span>-rw-r--r-- sk/users 53632 2018-06-29 15:57 ostechnix/image.jpg</span></span>
<span class="line"><span>-rw-r--r-- sk/users 156831 2018-06-04 12:37 ostechnix/file.pdf</span></span>
<span class="line"><span>-rw-r--r-- sk/users 9702219 2018-04-25 20:35 ostechnix/song.mp3</span></span></code></pre></div><h4 id="_3、使用-rar-命令" tabindex="-1">3、使用 rar 命令 <a class="header-anchor" href="#_3、使用-rar-命令" aria-label="Permalink to “3、使用 rar 命令”">​</a></h4><p>要查看一個 rar 文件的內容，只需要執行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ rar v ostechnix.rar</span></span>
<span class="line"><span></span></span>
<span class="line"><span>RAR 5.60 Copyright (c) 1993-2018 Alexander Roshal 24 Jun 2018</span></span>
<span class="line"><span>Trial version Type &#39;rar -?&#39; for help</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Archive: ostechnix.rar</span></span>
<span class="line"><span>Details: RAR 5</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Attributes Size Packed Ratio Date Time Checksum Name</span></span>
<span class="line"><span>----------- --------- -------- ----- ---------- ----- -------- ----</span></span>
<span class="line"><span>-rw-r--r-- 53632 52166 97% 2018-06-29 15:57 70260AC4 ostechnix/image.jpg</span></span>
<span class="line"><span>-rw-r--r-- 156831 139094 88% 2018-06-04 12:37 C66C545E ostechnix/file.pdf</span></span>
<span class="line"><span>-rw-r--r-- 9702219 9658527 99% 2018-04-25 20:35 DD875AC4 ostechnix/song.mp3</span></span>
<span class="line"><span>----------- --------- -------- ----- ---------- ----- -------- ----</span></span>
<span class="line"><span>9912682 9849787 99% 3</span></span></code></pre></div><h4 id="_4、使用-unrar-命令" tabindex="-1">4、使用 unrar 命令 <a class="header-anchor" href="#_4、使用-unrar-命令" aria-label="Permalink to “4、使用 unrar 命令”">​</a></h4><p>你也可以使用帶有 <code>l</code> 選項的 <code>unrar</code> 來做到與上面相同的事情，展示如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ unrar l ostechnix.rar</span></span>
<span class="line"><span></span></span>
<span class="line"><span>UNRAR 5.60 freeware Copyright (c) 1993-2018 Alexander Roshal</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Archive: ostechnix.rar</span></span>
<span class="line"><span>Details: RAR 5</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Attributes Size Date Time Name</span></span>
<span class="line"><span>----------- --------- ---------- ----- ----</span></span>
<span class="line"><span>-rw-r--r-- 53632 2018-06-29 15:57 ostechnix/image.jpg</span></span>
<span class="line"><span>-rw-r--r-- 156831 2018-06-04 12:37 ostechnix/file.pdf</span></span>
<span class="line"><span>-rw-r--r-- 9702219 2018-04-25 20:35 ostechnix/song.mp3</span></span>
<span class="line"><span>----------- --------- ---------- ----- ----</span></span>
<span class="line"><span>9912682 3</span></span></code></pre></div><h4 id="_5、使用-zip-命令" tabindex="-1">5、使用 zip 命令 <a class="header-anchor" href="#_5、使用-zip-命令" aria-label="Permalink to “5、使用 zip 命令”">​</a></h4><p>為了查看一個 zip 文件的內容而無需解壓它，可以使用下面的 <code>zip</code> 命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ zip -sf ostechnix.zip</span></span>
<span class="line"><span>Archive contains:</span></span>
<span class="line"><span>Life advices.jpg</span></span>
<span class="line"><span>Total 1 entries (597219 bytes)</span></span></code></pre></div><h4 id="_6、使用-unzip-命令" tabindex="-1">6、使用 unzip 命令 <a class="header-anchor" href="#_6、使用-unzip-命令" aria-label="Permalink to “6、使用 unzip 命令”">​</a></h4><p>你也可以像下面這樣使用 <code>-l</code> 選項的 <code>unzip</code> 命令來呈現一個 zip 文件的內容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ unzip -l ostechnix.zip</span></span>
<span class="line"><span>Archive: ostechnix.zip</span></span>
<span class="line"><span>Length Date Time Name</span></span>
<span class="line"><span>--------- ---------- ----- ----</span></span>
<span class="line"><span>597219 2018-04-09 12:48 Life advices.jpg</span></span>
<span class="line"><span>--------- -------</span></span>
<span class="line"><span>597219 1 file</span></span></code></pre></div><h4 id="_7、使用-zipinfo-命令" tabindex="-1">7、使用 zipinfo 命令 <a class="header-anchor" href="#_7、使用-zipinfo-命令" aria-label="Permalink to “7、使用 zipinfo 命令”">​</a></h4><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ zipinfo ostechnix.zip</span></span>
<span class="line"><span>Archive: ostechnix.zip</span></span>
<span class="line"><span>Zip file size: 584859 bytes, number of entries: 1</span></span>
<span class="line"><span>-rw-r--r-- 6.3 unx 597219 bx defN 18-Apr-09 12:48 Life advices.jpg</span></span>
<span class="line"><span>1 file, 597219 bytes uncompressed, 584693 bytes compressed: 2.1%</span></span></code></pre></div><p>如你所見，上面的命令展示了一個 zip 文件的內容、它的權限、創建日期和壓縮百分比等等信息。</p><h4 id="_8、使用-zcat-命令" tabindex="-1">8、使用 zcat 命令 <a class="header-anchor" href="#_8、使用-zcat-命令" aria-label="Permalink to “8、使用 zcat 命令”">​</a></h4><p>要一個壓縮的歸檔文件的內容而不解壓它，使用 <code>zcat</code> 命令，我們可以得到：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ zcat ostechnix.tar.gz</span></span></code></pre></div><p><code>zcat</code> 和 <code>gunzip -c</code> 命令相同。所以你可以使用下面的命令來查看歸檔或者壓縮文件的內容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ gunzip -c ostechnix.tar.gz</span></span></code></pre></div><h4 id="_9、使用-zless-命令" tabindex="-1">9、使用 zless 命令 <a class="header-anchor" href="#_9、使用-zless-命令" aria-label="Permalink to “9、使用 zless 命令”">​</a></h4><p>要使用 zless 命令來查看一個歸檔或者壓縮文件的內容，只需：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ zless ostechnix.tar.gz</span></span></code></pre></div><p>這個命令類似於 <code>less</code> 命令，它將一頁一頁地展示其輸出。</p><h4 id="_10、使用-less-命令" tabindex="-1">10、使用 less 命令 <a class="header-anchor" href="#_10、使用-less-命令" aria-label="Permalink to “10、使用 less 命令”">​</a></h4><p>可能你已經知道 <code>less</code> 命令可以打開文件來交互式地閲讀它，並且它支持滾動和搜索。</p><p>運行下面的命令來使用 <code>less</code> 命令查看一個歸檔或者壓縮文件的內容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ less ostechnix.tar.gz</span></span></code></pre></div><p>上面便是全部的內容了。現在你知道了如何在 Linux 中使用各種命令查看一個歸檔或者壓縮文件的內容了。希望本文對你有用。更多好的內容將呈現給大家，希望繼續關注我們！</p><p>乾杯！</p><hr>`,46)),p("p",null,[s[1]||(s[1]=a("via: ",-1)),e(n,{href:"https://www.ostechnix.com/how-to-view-the-contents-of-an-archive-or-compressed-file-without-extracting-it/"},{default:i(()=>[...s[0]||(s[0]=[a("https://www.ostechnix.com/how-to-view-the-contents-of-an-archive-or-compressed-file-without-extracting-it/",-1)])]),_:1})]),p("p",null,[s[6]||(s[6]=a("作者：",-1)),e(n,{href:"https://www.ostechnix.com/author/sk/"},{default:i(()=>[...s[2]||(s[2]=[a("SK",-1)])]),_:1}),s[7]||(s[7]=a(" 選題：",-1)),e(n,{href:"https://github.com/lujun9972"},{default:i(()=>[...s[3]||(s[3]=[a("lujun9972",-1)])]),_:1}),s[8]||(s[8]=a(" 譯者：",-1)),e(n,{href:"https://github.com/FSSlc"},{default:i(()=>[...s[4]||(s[4]=[a("FSSlc",-1)])]),_:1}),s[9]||(s[9]=a(" 校對：",-1)),e(n,{href:"https://github.com/wxy"},{default:i(()=>[...s[5]||(s[5]=[a("wxy",-1)])]),_:1})]),p("p",null,[s[12]||(s[12]=a("本文由 ",-1)),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[10]||(s[10]=[a("LCTT",-1)])]),_:1}),s[13]||(s[13]=a(" 原創編譯，",-1)),e(n,{href:"https://linux.cn/"},{default:i(()=>[...s[11]||(s[11]=[a("Linux中國",-1)])]),_:1}),s[14]||(s[14]=a(" 榮譽推出",-1))])])}const C=t(c,[["render",d]]);export{v as __pageData,C as default};
